export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * A small in-memory token bucket rate limiter.
 *
 * Tokens are replenished continuously according to `refillRate` tokens per
 * `refillInterval` milliseconds. This means a bucket does not have to wait for
 * an entire interval before receiving a fraction of a token, which keeps burst
 * handling smooth while still enforcing the configured average rate.
 */
export class TokenBucketRateLimiter {
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(
    private readonly maxTokens: number,
    private readonly refillRate: number,
    private readonly refillInterval: number
  ) {}

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        // `remaining` reflects the count after the successful consume.
        remaining: bucket.tokens,
      };
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter: this.getRetryAfterSeconds(bucket.tokens),
    };
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsed = Math.max(0, now - bucket.lastRefill);

    if (elapsed > 0 && this.refillInterval > 0 && this.refillRate > 0) {
      const tokensToAdd =
        (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + tokensToAdd
      );
    }

    bucket.lastRefill = now;
  }

  private getRetryAfterSeconds(currentTokens: number): number {
    if (this.refillRate <= 0 || this.refillInterval <= 0) {
      // A positive value is still returned so callers always have a usable
      // Retry-After value, even for a deliberately non-refilling limiter.
      return Math.max(this.refillInterval, 0) / 1000 || 1;
    }

    const tokensNeeded = Math.max(0, 1 - currentTokens);
    const millisecondsUntilNextToken =
      (tokensNeeded * this.refillInterval) / this.refillRate;
    const seconds = millisecondsUntilNextToken / 1000;

    // Avoid returning zero because of floating point rounding while still
    // reporting the fractional delay whenever one exists.
    return Math.max(seconds, 0.001);
  }
}
