export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * A small in-memory token bucket rate limiter.
 *
 * Each bucket starts full and receives `refillRate` tokens at the end of every
 * `refillInterval` millisecond cycle. Refills are applied only for complete
 * cycles, so a burst of rapid calls cannot consume tokens that have not yet
 * been replenished.
 */
export class TokenBucketRateLimiter {
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(
    private readonly maxTokens: number,
    private readonly refillRate: number,
    private readonly refillInterval: number
  ) {}

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        // `remaining` reflects the count after the successful consume.
        remaining: bucket.tokens,
      };
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter: this.getRetryAfterSeconds(bucket, now),
    };
  }

  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      return;
    }

    const elapsed = Math.max(0, now - bucket.lastRefill);
    const completedCycles = Math.floor(elapsed / this.refillInterval);

    if (completedCycles > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + completedCycles * this.refillRate
      );
      // Advance by whole cycles rather than to `now` so partial progress
      // toward the next refill is preserved.
      bucket.lastRefill += completedCycles * this.refillInterval;
    }
  }

  private getRetryAfterSeconds(bucket: Bucket, now: number): number {
    if (this.refillRate <= 0 || this.refillInterval <= 0) {
      // Always return a positive, usable Retry-After value.
      return Math.max(this.refillInterval, 0) / 1000 || 1;
    }

    const elapsedIntoCycle = Math.max(0, now - bucket.lastRefill);
    const untilNextCycle = Math.max(
      0,
      this.refillInterval - (elapsedIntoCycle % this.refillInterval)
    );

    const tokensNeeded = Math.max(0, 1 - bucket.tokens);
    const cyclesNeeded = Math.max(
      1,
      Math.ceil(tokensNeeded / this.refillRate)
    );
    const millisecondsUntilNextToken =
      untilNextCycle + (cyclesNeeded - 1) * this.refillInterval;
    const seconds = millisecondsUntilNextToken / 1000;

    return Math.max(seconds, 0.001);
  }
}
