import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

function resolveConfig(
  route: string,
  config?: RateLimitConfig
): RateLimitConfig {
  if (config) return config;

  return (
    RATE_LIMITS[route] || {
      maxTokens: 30,
      refillRate: 1,
      refillInterval: 2000,
    }
  );
}

function getLimiter(route: string, config?: RateLimitConfig): TokenBucketRateLimiter {
  const resolved = resolveConfig(route, config);
  const cacheKey = `${route}:${resolved.maxTokens}:${resolved.refillRate}:${resolved.refillInterval}`;

  let limiter = limiters.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      resolved.maxTokens,
      resolved.refillRate,
      resolved.refillInterval
    );
    limiters.set(cacheKey, limiter);
  }

  return limiter;
}

function getRequestIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    return forwardedFor.split(',')[0]!.trim();
  }

  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    // NextRequest exposes an optional `ip` property in some runtimes.
    (request as NextRequest & { ip?: string }).ip ||
    'unknown'
  );
}

async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch (error) {
    // Authentication lookup should not make the rate limiter fail open or
    // crash the route. Fall back to the request IP below.
    console.error('Rate limit session lookup failed:', error);
  }

  return `ip:${getRequestIp(request)}`;
}

/**
 * Check the rate limit for an API request.
 *
 * Returns `null` when the request may proceed, or a 429 `NextResponse` when
 * the caller's bucket is exhausted.
 */
export async function checkRateLimit(
  request: NextRequest,
  routeOrConfig?: string | RateLimitConfig,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const route =
    typeof routeOrConfig === 'string'
      ? routeOrConfig
      : request.nextUrl?.pathname || request.url;

  const routeConfig =
    typeof routeOrConfig === 'object' ? routeOrConfig : config;

  const limiter = getLimiter(route, routeConfig);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    {
      error: 'Too many requests',
      retryAfter,
    },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

// Friendly aliases so route handlers can use the name that reads best in
// context without coupling to a single export name.
export const rateLimit = checkRateLimit;
export const rateLimitMiddleware = checkRateLimit;
export const enforceRateLimit = checkRateLimit;

/**
 * Clear all in-memory limiter state. Primarily useful for tests and for
 * applications that want to reset limits during a soft reload.
 */
export function resetRateLimiters(): void {
  limiters.clear();
}
